// Pre-rendered bitmap fonts (generated by gen_fonts.py) and text measuring.
// Platform-free; the glyph data lives in font_data.cpp.
#pragma once

#include <cstdint>

namespace chord {

enum class FontRole : uint8_t {
    Ui,    // Pillow's default font (Aileron): small labels
    Mono,  // DejaVu Sans Mono Bold: tags and status text
    Big,   // Inter Black: chord names (digits, note letters and chord qualities only)
};

struct Glyph {
    int16_t bx0, by0, bx1, by1;  // Pillow's glyph box relative to the baseline origin (y negative = above)
    int16_t left, top;           // ink bitmap: x = pen + left, first row = baseline - top
    uint8_t w, h;                // ink bitmap size in pixels (0 for blank glyphs)
    uint8_t adv;                 // advance in pixels
    int8_t shift;                // row-rounding class: see Canvas::text
    uint32_t offset;             // start of the bitmap in the bit table (rows padded to bytes, MSB first)
};

struct FontFace {
    FontRole role;
    int size;
    int ascent;
    int descent;
    const char* chars;           // characters this face has glyphs for, parallel to glyphs[]
    const Glyph* glyphs;
    int count;
};

namespace fontdata {
extern const uint8_t kBits[];
extern const int kBitCount;
extern const FontFace kFaces[];
extern const int kFaceCount;
}  // namespace fontdata

// The face for a role at exactly this size, or nullptr.
const FontFace* font_find(FontRole role, int size);

// Sizes available for a role, largest first. Returns the count (at most cap).
int font_sizes(FontRole role, int* out, int cap);

// Glyph for a character, or nullptr if the face does not have it.
const Glyph* font_glyph(const FontFace& face, char c);

// Text extents relative to the baseline origin, the same numbers Pillow's getbbox
// returns for anchor "ls" in 1-bit mode: x0 <= 0, y0 < 0 above the baseline.
struct TextExtent {
    int x0, y0, x1, y1;
    int advance;
};
TextExtent text_extent(const FontFace& face, const char* s);

}  // namespace chord
